import {mountCalculator} from './calculator.js';
import {generate,checkAnswer,skills} from './math.js';
import {diagram,shapeSVG} from './diagrams.js';
import {KEY,readHistory,stats,adaptive} from './progress.js';
const tabs=[['triangle','Triangle Area'],['base','Base & Height'],['missing','Missing Dimension'],['grid','Grid Triangles'],['polygon','Polygon Area'],['challenge','Challenge Mix'],['multiplication','Multiplication'],['progress','Progress']];
let history=readHistory(localStorage),mode='triangle',difficulty='Easy',length=10,level=0,session=[],p,hints=0,attempts=0,done=false,explained=false,heightShown=false,feedback='',good=false,answer='',selected=[],yes=null,reason='',range='All Time',complete=false,record=null,saveFailed=false,partialValues=[];
const app=document.querySelector('#app'),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const calculator=mountCalculator(value=>{const input=document.querySelector('#answer:not(:disabled)');if(input){answer=value;input.value=value;input.scrollIntoView({block:'nearest'});}});
function save(){try{localStorage.setItem(KEY,JSON.stringify(history));saveFailed=false}catch{saveFailed=true}}
function newProblem(){if(difficulty==='Adaptive'){level=adaptive(session,level)}p=generate(mode,difficulty==='Adaptive'?['Easy','Medium','Hard'][level]:difficulty);hints=difficulty==='Adaptive'&&session.slice(-3).filter(r=>!r.correct).length>=2?1:0;attempts=0;done=false;explained=false;heightShown=false;feedback='';good=false;answer='';selected=[];yes=null;reason='';record=null;partialValues=[];render()}
function start(next=mode){mode=next;session=[];complete=false;level=0;if(mode==='progress')render();else newProblem()}
function recordAttempt(correct){if(record)return;record={skill:p.skill,correct,hints,time:Date.now()};history.push(record);session.push(record);save()}
function submit(){if(done)return;const raw=p.type==='identification'?selected:p.type==='reasoning'?{yes,reason}:answer;if(p.type==='identification'&&!selected.length){feedback='Select at least one shape.';render();return}if(p.type==='reasoning'&&(yes===null||!reason)){feedback='Choose Yes or No and select a reason.';render();return}let result=checkAnswer(p,raw);if(result.invalid){feedback=result.message;render();return}attempts++;recordAttempt(result.correct);good=result.correct;done=result.correct;feedback=result.correct?'Nicely done. '+(attempts>1?'Your practice paid off.':'You got it on your first try.'):result.message;if(done){explained=true;if(p.type==='multiplication'){let wrong=partialValues.some((v,i)=>v.trim()!==''&&Number(v.replace(/,/g,''))!==p.partials[i]);if(wrong)feedback+=' Your final product is correct; check the optional partial products against the steps below.'}}render();if(!done&&matchMedia('(pointer:fine)').matches)document.querySelector('#answer')?.focus()}
function next(){if(!record)return;if(length&&session.length>=length){complete=true;render()}else newProblem()}
function header(){return `<header><div class="brand"><span class="logo">△</span><div><div class="eyebrow" style="margin-bottom:5px">A little practice. A lot of progress.</div>6th Grade Math Practice</div></div><div class="header-actions"><button class="primary" data-mode="mixed">✦ Mixed Practice</button></div></header><nav aria-label="Practice topics">${tabs.map(([id,name])=>`<button data-mode="${id}" class="${mode===id?'active':''}" ${mode===id?'aria-current="page"':''}>${name}</button>`).join('')}</nav>`}
function settings(){return `<div class="settings"><label class="small">DIFFICULTY<select id="difficulty">${['Easy','Medium','Hard','Adaptive'].map(x=>`<option ${x===difficulty?'selected':''}>${x}</option>`).join('')}</select></label><label class="small">SESSION LENGTH<select id="length">${[5,10,20,0].map(x=>`<option value="${x}" ${x===length?'selected':''}>${x?x+' Questions':'Unlimited Practice'}</option>`).join('')}</select></label></div>`}
function sidebar(){let s=stats(session);return `<aside class="sidebar"><section class="card asidecard"><h3>Your session</h3><div class="statrow"><span class="muted">First-try score</span><strong>${s.correct}<span class="muted" style="font-size:16px"> / ${s.attempted}</span></strong></div><div class="statrow"><span class="muted">Current streak</span><strong>${s.streak} <span style="color:#d69739">✦</span></strong></div><div class="bar" role="progressbar" aria-label="Session progress" aria-valuenow="${session.length}" aria-valuemin="0" aria-valuemax="${length||Math.max(1,session.length)}"><div style="width:${length?Math.min(100,session.length/length*100):0}%"></div></div><p class="tiny muted">${length?session.length+' of '+length+' questions attempted':'Unlimited · go at your own pace'}</p></section><section class="card asidecard tip"><div class="eyebrow">${mode==='challenge'||mode==='mixed'?'Your approach':'Keep in mind'}</div>${mode==='challenge'||mode==='mixed'?'<p>Read carefully. Decide which measurements matter before choosing a strategy.</p>':p.type==='multiplication'?'<div class="formula">Place value matters.</div><p>Multiply ones, tens, and hundreds separately. Then add.</p>':'<div class="formula">A = ½ × b × h</div><p>The height meets the selected base at a right angle. A slanted side is not always the height.</p>'}</section></aside>`}
function questionInput(){if(p.type==='identification')return `<div class="choices">${p.options.map(s=>`<button type="button" class="choice ${selected.includes(s.id)?'selected':''}" data-shape="${s.id}" aria-pressed="${selected.includes(s.id)}" ${done?'disabled':''}>${shapeSVG(s)}<span>${s.name}</span></button>`).join('')}</div><div class="answerrow"><button class="primary" ${done?'disabled':''}>Check selection</button></div>`;if(p.type==='reasoning')return `<div class="answerrow">${[true,false].map(v=>`<button type="button" data-yes="${v}" aria-pressed="${yes===v}" class="${yes===v?'selected':''}" ${done?'disabled':''}>${v?'Yes':'No'}</button>`).join('')}</div><div class="reasonchoices">${p.reasons.map(r=>`<button type="button" data-reason="${r.id}" class="${reason===r.id?'selected':''}" aria-pressed="${reason===r.id}" ${done?'disabled':''}>${r.text}</button>`).join('')}</div><div class="answerrow"><button class="primary" ${done?'disabled':''}>Check reasoning</button></div>`;return `${p.type==='multiplication'?`<details><summary>Optional partial products</summary><p class="tiny muted">Enter products in order: ones, tens, then hundreds.</p><div class="partials">${p.partials.map((_,i)=>`<label class="small">${['Ones','Tens','Hundreds'][i]}<input data-partial="${i}" aria-label="${['Ones','Tens','Hundreds'][i]} partial product" inputmode="numeric" value="${escape(partialValues[i]||'')}" ${done?'disabled':''}></label>`).join('')}</div></details>`:''}<label for="answer" style="display:block;margin-top:18px;font-size:14px;font-weight:600">Your answer</label><div class="answerrow numeric-answer"><div class="answer-entry"><div class="inputwrap"><input id="answer" type="number" step="any" autocomplete="off" inputmode="${p.type==='multiplication'?'numeric':'decimal'}" enterkeyhint="done" placeholder="Enter your answer" value="${escape(answer)}" ${done?'disabled':''}><span class="unit">${p.units}</span></div><button type="button" id="calculator-toggle" aria-label="Open calculator" title="Calculator" aria-controls="calculator" aria-expanded="false"><svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><rect x="5" y="2" width="14" height="20" rx="2"/><path d="M8 6h8v4H8zM8 14h2m4 0h2M8 18h2m4 0h2"/></svg></button></div><button class="primary" ${done?'disabled':''}>Check answer <span aria-hidden="true">↵</span></button></div>`}
function practice(){let title=mode==='mixed'?'Mixed Practice':tabs.find(t=>t[0]===mode)?.[1];return `<div class="heading"><div><div class="eyebrow">${mode==='multiplication'?'Spiral review':'Geometry · Area & measurement'}</div><h1>${title}</h1><div class="muted">One problem at a time. Build your confidence.</div></div>${settings()}</div><div class="layout"><section class="card"><div class="cardtop"><span>QUESTION ${session.length+(record?0:1)}${length?' OF '+length:''}</span><span class="badge">${p.difficulty}${difficulty==='Adaptive'?' · Adaptive':''}</span></div><div class="problem"><h2>${p.prompt}</h2>${p.type==='multiplication'?`<div class="multiplication" aria-label="${p.a} times ${p.b}"><div>${p.a.toLocaleString('en-US')}</div><div>× ${p.b}</div></div>`:diagram(p,hints,heightShown)}<form id="answerform">${questionInput()}</form><div aria-live="polite">${feedback?`<div class="feedback ${good?'good':''}">${feedback}</div>`:''}${hints?`<div class="hint"><strong>Hint ${hints}</strong> · ${p.hints[hints-1]}</div>`:''}${explained?`<div class="explanation"><strong>Let's work it through</strong>\n${p.explanation}</div>`:''}</div><div class="actions"><button id="hint" ${hints>=p.hints.length||done?'disabled':''}>☼ ${hints?'Next hint':'Get a hint'}</button>${p.type==='grid'?`<button id="height">${heightShown?'Hide':'Show'} height</button>`:''}${attempts>0&&!done?`<button id="explain">${attempts<2?'Explanation after next attempt':'Show explanation'}</button>`:''}<button class="next ${done?'primary':''}" id="next" ${record?'':'disabled'}>${length&&session.length>=length?'Finish practice':'Next problem'} →</button></div></div></section>${sidebar()}</div><div class="footer-note">${saveFailed?'Progress could not be saved. Check your browser storage settings.':'Progress saves automatically on this device. Every attempt is a chance to learn.'}</div>`}
function progress(){let now=new Date(),cutoff=range==='Today'?new Date(now.getFullYear(),now.getMonth(),now.getDate()).getTime():range==='Last 7 Days'?Date.now()-7*86400000:0,rows=history.filter(r=>r.time>=cutoff);return `<div class="heading"><div><div class="eyebrow">Your learning journey</div><h1>Progress & mastery</h1><p class="muted">Mastery emphasizes your 12 most recent attempts.</p></div><label class="small">TIME RANGE<select id="range">${['Today','Last 7 Days','All Time'].map(r=>`<option ${r===range?'selected':''}>${r}</option>`).join('')}</select></label></div><div class="progressgrid">${skills.map(skill=>{let s=stats(rows.filter(r=>r.skill===skill));return `<section class="card"><div class="eyebrow">${s.mastery}</div><h2>${skill}</h2><div class="statrow"><strong>${s.accuracy}%</strong><span class="muted">${s.correct} / ${s.attempted} first try</span></div><div class="bar"><div style="width:${s.accuracy}%"></div></div><p class="metrics"><span>Streak ${s.streak}</span><span>Best ${s.best}</span><span>Hints ${s.hints}</span></p></section>`}).join('')}</div><p class="muted tiny">A question is scored on the first submitted attempt. Retries help you learn without adding extra attempts.</p><button id="reset">Reset Progress</button><dialog id="resetdialog"><h2>Reset all progress?</h2><p>This erases saved attempts on this device. This cannot be undone.</p><button id="cancelreset">Keep progress</button> <button id="confirmreset" class="primary">Reset progress</button></dialog>`}
function summary(){let s=stats(session),groups=skills.map(skill=>({skill,...stats(session.filter(r=>r.skill===skill))})).filter(x=>x.attempted),weak=groups.slice().sort((a,b)=>a.accuracy-b.accuracy)[0];return `<section class="card summary"><div class="eyebrow">You showed up. That counts.</div><h1>Practice Complete</h1><div class="score">${s.correct}<span class="muted" style="font-size:32px"> / ${s.attempted}</span></div><p>${s.accuracy}% first-try accuracy</p>${groups.map(g=>`<div class="skillresult"><span>${g.skill}</span><strong>${g.correct}/${g.attempted}</strong></div>`).join('')}<p>${weak.accuracy<80?'Keep building your confidence in '+weak.skill.toLowerCase()+'. Try that section next.':'Strong work across this session. Try a higher difficulty to stretch your skills.'}</p><button class="primary" id="restart">Practice again</button> <button data-mode="progress">View progress</button></section>`}
function render(){app.innerHTML=header()+`<main>${mode==='progress'?progress():complete?summary():practice()}</main>`;calculator.update();document.querySelector('#calculator-toggle')?.addEventListener('click',()=>calculator.toggle());document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>start(b.dataset.mode));document.querySelector('#difficulty')?.addEventListener('change',e=>{difficulty=e.target.value;start()});document.querySelector('#length')?.addEventListener('change',e=>{length=Number(e.target.value);start()});document.querySelector('#answerform')?.addEventListener('submit',e=>{e.preventDefault();submit()});document.querySelector('#answer')?.addEventListener('input',e=>answer=e.target.value);document.querySelectorAll('[data-partial]').forEach(i=>i.oninput=()=>partialValues[Number(i.dataset.partial)]=i.value);document.querySelectorAll('[data-shape]').forEach(b=>b.onclick=()=>{selected=selected.includes(b.dataset.shape)?selected.filter(s=>s!==b.dataset.shape):[...selected,b.dataset.shape];render()});document.querySelectorAll('[data-yes]').forEach(b=>b.onclick=()=>{yes=b.dataset.yes==='true';render()});document.querySelectorAll('[data-reason]').forEach(b=>b.onclick=()=>{reason=b.dataset.reason;render()});document.querySelector('#hint')?.addEventListener('click',()=>{hints++;if(record){record.hints=hints;save()}render()});document.querySelector('#height')?.addEventListener('click',()=>{heightShown=!heightShown;if(heightShown&&hints===0){hints=1;if(record){record.hints=hints;save()}}render()});document.querySelector('#explain')?.addEventListener('click',()=>{if(attempts<2){feedback='Try once more first. Use a hint to guide your next attempt.'}else{explained=true;done=true}render()});document.querySelector('#next')?.addEventListener('click',next);document.querySelector('#restart')?.addEventListener('click',()=>start());document.querySelector('#range')?.addEventListener('change',e=>{range=e.target.value;render()});document.querySelector('#reset')?.addEventListener('click',()=>document.querySelector('#resetdialog').showModal());document.querySelector('#cancelreset')?.addEventListener('click',()=>document.querySelector('#resetdialog').close());document.querySelector('#confirmreset')?.addEventListener('click',()=>{history=[];session=[];save();render()})}
newProblem();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'start_math_practice',description:'Start a new practice session for a selected math topic.',inputSchema:{type:'object',properties:{topic:{type:'string',enum:[...tabs.filter(t=>t[0]!=='progress').map(t=>t[0]),'mixed']}},required:['topic'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!tabs.some(t=>t[0]===input.topic)&&input.topic!=='mixed')throw Error('Invalid topic');start(input.topic);return {topic:mode,prompt:p.prompt}}})).catch(()=>{})}catch{}}

